pub fn packet_crc(crc: u16, byte: u8) -> u16 {
    let mut remainder: u16 = crc;
    for bit in ((0u64 as u8) as u8)..(8u8 as u8) {
        let feedback: bool =
            ((Int::shr(remainder, 15) & 1u16) != (Int::shr(u16::from(byte), (bit as u64)) & 1u16));
        remainder = if feedback {
            ((Int::shl(remainder, 1) ^ 32773u16) & 65535u16)
        } else {
            (Int::shl(remainder, 1) & 65535u16)
        };
    }
    return remainder;
}

